-- migration_53_move_series_content.sql
-- Replaces the Move pillar's content and card structure for all 196 weeks
-- (pregnancy weeks 1-39, postpartum weeks 0-156 / week_number 40-196) with
-- the full "Move" series drafted, reviewed, and locked separately (see the
-- 11 locked "Move - ..." documents and CLAUDE.md). No column/type change --
-- `move` was already jsonb (migration_33) and stays jsonb; only its internal
-- shape changes. Every other field on this table (theme_title, mantra,
-- nourish, hydration_goal, feeding_comfort, rest_support, reset, care_for_
-- yourself, your_corner, support_moment, celebrate_this_week, mental_health_
-- note, for_your_care_team, condition_notes, closing_note) is UNTOUCHED --
-- this migration only ever writes to the move column.
--
-- New move shape (all keys optional except format/theme/mantra/exercise/why/
-- safety/closingLabel/closingText, which are always present):
--   format: "tiers3" (First trimester weeks 1-9 only, Restore/Rebuild/Thrive
--     as three separate named tiers) | "sections" (everything else, Reset/
--     Move/Build/Release headers)
--   theme, mantra: this week's own Move-specific headline/quote (distinct
--     from the week's overall theme_title/mantra elsewhere on this row)
--   tiers: { restore: string[], rebuild: string[], thrive: string[] } --
--     only present when format = "tiers3"
--   reset, today, build (string[]), release, recoveryRoute (object, vaginal/
--     assisted-birth vs caesarean framing, Early Healing + Finding Rhythm
--     only), door (Comfort/Steady/Challenge, Year Three only) -- present
--     when format = "sections"
--   exercise: { name, focus, benefit, mistake, tip }
--   inRealLife, why, quote, note, clinicalFlag, progressionNote, safety,
--   recovery (string[], postpartum recovery-check items),
--   reflectionPrompt, closingLabel, closingText, lookingAhead
--   milestone, breathLegacy, philosophy -- phase-closing callbacks, present
--     only on each phase's final week
--   childLearned (string[]) -- "What Your Child Learned Watching You",
--     present only on each postpartum phase's final week (46, 52, 66, 92,
--     118, 144, 170, 196)
--   whatYouGaveYourself (string[]), finalNote, signatureLine (string[2]) --
--     present only on week 196, the true close of the whole three-year
--     journey
--
-- Not yet independently clinically verified beyond the pass already logged
-- in move-series-clinical-verification-2026-08-03.md -- the one open item
-- is Second trimester week 19's Standing Wood Chop (clinicalFlag on that
-- row), which still needs real OB/GYN + pelvic-health-physiotherapist review
-- before being treated as settled either way.

UPDATE care_chart_week_content SET move = $movejson${"format":"tiers3","tiers":{"restore":["A few slow, deep breaths before you start","3 minute gentle walk","Ankle circles — 8 per side"],"rebuild":["A few slow, deep breaths before you start","10 minute conversational walk","Standing march, holding support — 2x10 per side","Calf stretch — 30 sec per side"],"thrive":["A few slow, deep breaths before you start","20 minutes of familiar moderate activity (whatever you already do)","One easy round: Standing march 10 per side, Wall Angels 8, Supported calf raises 10"]},"exercise":{"name":"Ankle Circles","focus":"ankle mobility and circulation","benefit":"Keeps blood moving through your lower legs — small effort, real value as blood volume starts rising.","mistake":"Rushing through them without a full circle.","tip":"Go slowly, both directions, both sides."},"inRealLife":null,"why":"Nothing needs to change yet — your body hasn't needed to adapt yet either, so matching effort to demand is the whole strategy this early.","note":null,"safety":"Use stable support, breathe continuously, and keep effort conversational throughout. Stop for pain, bleeding, dizziness, chest pain, breathlessness before exertion, fluid leakage, calf pain or swelling, or anything that feels wrong.","closingLabel":"If today doesn't happen","closingText":"Not moving today doesn't make this week any less real, either.","lookingAhead":"Next week looks much like this one — small, steady movement while your body quietly gets to work. There's no rush to feel different yet.","clinicalFlag":null,"theme":"The quiet beginning","mantra":"You do not have to feel different yet for this to be real.","progressionNote":null,"quote":null,"recovery":null,"recoveryRoute":null,"door":null,"reflectionPrompt":null,"milestone":null,"breathLegacy":null,"philosophy":null,"childLearned":null,"whatYouGaveYourself":null,"finalNote":null,"signatureLine":null,"today":null,"build":null,"move":null,"release":null,"reset":null}$movejson$::jsonb WHERE week_number = 1;
UPDATE care_chart_week_content SET move = $movejson${"format":"tiers3","tiers":{"restore":["A slow breath in, longer breath out, five times","3 minute gentle walk","Shoulder rolls — 10"],"rebuild":["A slow breath in, longer breath out, five times","10 minute conversational walk","Standing Hip Abduction, holding support — 2x10 per side"],"thrive":["A slow breath in, longer breath out, five times","20 minutes of familiar moderate activity","One easy round: Standing Hip Abduction 10 per side, Mini Squats 10, Wall Angels 8"]},"exercise":{"name":"Standing Hip Abduction","focus":"hip and pelvic stability","benefit":"Supports the joints that will carry more load as pregnancy progresses.","mistake":"Leaning your torso sideways instead of staying upright.","tip":"Hold something stable and move slowly — this isn't about how high your leg lifts."},"inRealLife":null,"why":"There's nothing to protect against yet, so there's nothing urgent to build for either — that comes soon, not now.","note":null,"safety":"Use stable support, breathe continuously, and keep effort conversational throughout. Stop for pain, bleeding, dizziness, chest pain, breathlessness before exertion, fluid leakage, calf pain or swelling, or anything that feels wrong.","closingLabel":"If today doesn't happen","closingText":"Feeling different isn't the marker of progress here — showing up in any way, or not at all today, still counts.","lookingAhead":"Week 3 continues gently too — we'll bring in a little more balance and core awareness, always without any strain.","clinicalFlag":null,"theme":"The quiet beginning","mantra":"You do not have to feel different yet for this to be real.","progressionNote":null,"quote":null,"recovery":null,"recoveryRoute":null,"door":null,"reflectionPrompt":null,"milestone":null,"breathLegacy":null,"philosophy":null,"childLearned":null,"whatYouGaveYourself":null,"finalNote":null,"signatureLine":null,"today":null,"build":null,"move":null,"release":null,"reset":null}$movejson$::jsonb WHERE week_number = 2;
UPDATE care_chart_week_content SET move = $movejson${"format":"tiers3","tiers":{"restore":["Breathe into your belly, hand resting on it, five breaths","3 minute gentle walk","Thoracic rotations, seated or standing — 8 per side"],"rebuild":["Breathe into your belly, hand resting on it, five breaths","10 minute conversational walk","Bird Dog (or seated march if lying down isn't comfortable) — 2x6 per side"],"thrive":["Breathe into your belly, hand resting on it, five breaths","20 minutes of familiar moderate activity","One easy round: Bird Dog 8 per side, Thoracic rotations 8 per side, Supported calf raises 10"]},"exercise":{"name":"Bird Dog","focus":"core and balance coordination","benefit":"Trains deep core stabilisers safely, with no crunching motion at all.","mistake":"Letting your lower back arch as you extend.","tip":"Keep your back flat, like a tabletop, the whole time."},"inRealLife":null,"why":"Core work looks like Bird Dog, not crunches, because safe pregnancy core training builds stability, not sit-up strength — which is actually more useful anyway.","note":null,"safety":"Use stable support, breathe continuously, and keep effort conversational throughout. Stop for pain, bleeding, dizziness, chest pain, breathlessness before exertion, fluid leakage, calf pain or swelling, or anything that feels wrong.","closingLabel":"If today doesn't happen","closingText":"This week doesn't ask anything of you that today can't give — including nothing at all.","lookingAhead":"Next week, posture starts getting a little more attention — small habits that are far easier to build now than to fix later.","clinicalFlag":null,"theme":"The quiet beginning","mantra":"You do not have to feel different yet for this to be real.","progressionNote":null,"quote":null,"recovery":null,"recoveryRoute":null,"door":null,"reflectionPrompt":null,"milestone":null,"breathLegacy":null,"philosophy":null,"childLearned":null,"whatYouGaveYourself":null,"finalNote":null,"signatureLine":null,"today":null,"build":null,"move":null,"release":null,"reset":null}$movejson$::jsonb WHERE week_number = 3;
UPDATE care_chart_week_content SET move = $movejson${"format":"tiers3","tiers":{"restore":["Three slow sighing breaths — a bigger exhale than usual","3 minute gentle walk","Wall Pelvic Tilts — 6"],"rebuild":["Three slow sighing breaths — a bigger exhale than usual","10 minute conversational walk","Wall Angels — 8","Mini Squats — 8"],"thrive":["Three slow sighing breaths — a bigger exhale than usual","20 minutes of familiar moderate activity","One easy round: Mini Squats 10, Wall Angels 8, Wall Pelvic Tilts 6, Supported calf raises 10"]},"exercise":{"name":"Wall Angels","focus":"posture and shoulder mobility","benefit":"Counters the forward-rounding posture pregnancy can bring on surprisingly early.","mistake":"Forcing your arms flat against the wall.","tip":"Only go as far as feels natural — a small range done well beats a forced full range."},"inRealLife":null,"why":"Posture work starts this early because hormonal changes loosen your joints from week one, well before your bump does anything — easier to build good habits now than fix them later.","note":null,"safety":"Use stable support, breathe continuously, and keep effort conversational throughout. Stop for pain, bleeding, dizziness, chest pain, breathlessness before exertion, fluid leakage, calf pain or swelling, or anything that feels wrong.","closingLabel":"If today doesn't happen","closingText":"Four weeks in, quiet is still allowed to be the whole story.","lookingAhead":"The next few weeks often bring real tiredness as your body ramps up its biggest hidden work. We'll keep things light and let your energy lead, not the calendar.","clinicalFlag":null,"theme":"The quiet beginning","mantra":"You do not have to feel different yet for this to be real.","progressionNote":null,"quote":null,"recovery":null,"recoveryRoute":null,"door":null,"reflectionPrompt":null,"milestone":null,"breathLegacy":null,"philosophy":null,"childLearned":null,"whatYouGaveYourself":null,"finalNote":null,"signatureLine":null,"today":null,"build":null,"move":null,"release":null,"reset":null}$movejson$::jsonb WHERE week_number = 4;
UPDATE care_chart_week_content SET move = $movejson${"format":"tiers3","tiers":{"restore":["A few slow breaths, in through the nose, out through the mouth","3 minute slow walk","2 minutes of shoulder rolls"],"rebuild":["A few slow breaths, in through the nose, out through the mouth","8-10 minute easy walk","Standing march, holding support — 2x8 per side"],"thrive":["A few slow breaths, in through the nose, out through the mouth","15-20 minute walk","One easy round: Standing march 10 per side, Supported calf raises 10, Wall Angels 8"]},"exercise":{"name":"Standing March","focus":"gentle hip flexor activation","benefit":"Keeps your hips moving without any jarring impact — a good option on a genuinely low-energy day.","mistake":"Rushing the pace to make it feel like more.","tip":"Match your breath to each step — slow is the point, not a compromise."},"inRealLife":null,"why":"We're not pushing intensity this week because early pregnancy fatigue is a real physiological cost, not a motivation problem — backing off is the correct response.","note":"If nausea is loud this week, the Restore option is a completely adequate day — this phase is deliberately light on purpose.","safety":"Use stable support, breathe continuously, and keep effort conversational throughout. Stop for pain, bleeding, dizziness, chest pain, breathlessness before exertion, fluid leakage, calf pain or swelling, or anything that feels wrong.","closingLabel":"If today doesn't happen","closingText":"If today has no steps in it at all, that's a small week, not a failed one.","lookingAhead":"Next week may feel even more tiring—and that's completely expected. We'll keep movement gentle while your body does some of its biggest behind-the-scenes work.","clinicalFlag":null,"theme":"Your body is changing faster than it looks","mantra":"Small meals, small steps and small wins all count.","progressionNote":null,"quote":null,"recovery":null,"recoveryRoute":null,"door":null,"reflectionPrompt":null,"milestone":null,"br