UPDATE care_chart_week_content SET move = $movejson${"format":"tiers3","tiers":{"restore":["Breathe in for 4, out for 6, five rounds","2 minute walk","8 ankle circles per side"],"rebuild":["Breathe in for 4, out for 6, five rounds","8 minute walk","One gentle round: Wall Angels 8, Supported calf raises 10, Wall Pelvic Tilts 6"],"thrive":["Breathe in for 4, out for 6, five rounds","15-20 minutes of walking, swimming, or stationary cycling","10 minutes of easy mobility: Thoracic rotations, Wall Angels, gentle Standing Hip Abduction"]},"exercise":{"name":"Wall Pelvic Tilts","focus":"pelvic floor and lower back awareness","benefit":"Begins the pelvic-floor-and-breath connection you'll rely on for the rest of pregnancy and after birth.","mistake":"Holding your breath while tilting.","tip":"Exhale gently as you tilt — breath and movement work together, not against each other."},"inRealLife":null,"why":"Rest counts as real care this week because growing a placenta takes measurable energy — your exhaustion has an actual biological cause, not just a mental one.","note":null,"safety":"Use stable support, breathe continuously, and keep effort conversational throughout. Stop for pain, bleeding, dizziness, chest pain, breathlessness before exertion, fluid leakage, calf pain or swelling, or anything that feels wrong.","closingLabel":"If today doesn't happen","closingText":"Choosing rest over movement today isn't a flaw — it's exactly what this week is for.","lookingAhead":"Nausea may still be loud next week too — we'll keep leaning on whatever movement fits around it, at whatever time of day actually works for you.","clinicalFlag":null,"theme":"Rest is productive","mantra":"Exhaustion is not a character flaw.","progressionNote":null,"quote":null,"recovery":null,"recoveryRoute":null,"door":null,"reflectionPrompt":null,"milestone":null,"breathLegacy":null,"philosophy":null,"childLearned":null,"whatYouGaveYourself":null,"finalNote":null,"signatureLine":null,"today":null,"build":null