UPDATE care_chart_week_content SET move = $movejson${"format":"tiers3","tiers":{"restore":["A minute of slow breathing, wherever you are","3 minute walk in fresh or ventilated air","Calf stretch — 1 min per side"],"rebuild":["A minute of slow breathing, wherever you are","10 minute walk","5 minutes: Wall Angels, Supported calf raises, shoulder rolls"],"thrive":["A minute of slow breathing, wherever you are","20 minute walk or stationary cycle","One round: Standing march 10 per side, Standing Hip Abduction 10 per side, Supported calf raises 10"]},"exercise":{"name":"Cat-Cow","focus":"spinal mobility","benefit":"Eases the lower-back tension that often starts appearing around now.","mistake":"Moving too fast through the range.","tip":"Match one full breath to each direction — in as you arch, out as you round."},"inRealLife":null,"why":"Walking is enough some days because even light aerobic movement supports mood and circulation — it doesn't need to be more than that to be worthwhile.","note":"Move this to whenever symptoms are quietest today — morning, evening, whenever works.","safety":"Use stable support, breathe continuously, and keep effort conversational throughout. Stop for pain, bleeding, dizziness, chest pain, breathlessness before exertion, fluid leakage, calf pain or swelling, or anything that feels wrong.","closingLabel":"If today doesn't happen","closingText":"Movement can be just as flexible as nutrition — today, that might mean none at all.","lookingAhead":"An appointment may be coming up soon — next week's plan makes a little room for that kind of nervous energy too.","clinicalFlag":null,"theme":"Eat what works today","mantra":"Nutrition can be flexible while symptoms are loud.","progressionNote":null,"quote":null,"recovery":null,"recoveryRoute":null,"door":null,"reflectionPrompt":null,"milestone":null,"breathLegacy":null,"philosophy":null,"childLearned":null,"whatYouGaveYourself":null,"finalNote":null,"signatureLine":null,"today":null,"build":null,"move