UPDATE care_chart_week_content SET move = $movejson${"format":"tiers3","tiers":{"restore":["A slow breath in, longer breath out, five times","5 minute slow walk while relaxing hands and shoulders"],"rebuild":["A slow breath in, longer breath out, five times","10 minute walk","5 minutes: Thoracic rotations, wall pelvic tilts, gentle side stretches"],"thrive":["A slow breath in, longer breath out, five times","20 minutes of familiar moderate activity","10 minutes: Seated Band Row (light), Wall Angels, Mini Squats"]},"exercise":{"name":"Thoracic Rotations","focus":"upper-back mobility","benefit":"Loosens the mid-back — especially useful before or after a long appointment spent sitting.","mistake":"Twisting from the lower back instead of the ribcage.","tip":"Keep your hips still and rotate from your chest."},"inRealLife":null,"why":"Appointments deserve their own kind of care because anxiety before a scan is common and doesn't mean something's wrong — movement can genuinely help settle it.","note":null,"safety":"Use stable support, breathe continuously, and keep effort conversational throughout. Stop for pain, bleeding, dizziness, chest pain, breathlessness before exertion, fluid leakage, calf pain or swelling, or anything that feels wrong.","closingLabel":"If today doesn't happen","closingText":"You don't need to arrive at today's movement either, if it isn't there.","lookingAhead":"Week 9 can be one of the hardest of this trimester for many mothers — if that's you, the plan gets even smaller to meet you there.","clinicalFlag":null,"theme":"Care can include appointments","mantra":"You do not need to arrive with every question answered.","progressionNote":null,"quote":null,"recovery":null,"recoveryRoute":null,"door":null,"reflectionPrompt":null,"milestone":null,"breathLegacy":null,"philosophy":null,"childLearned":null,"whatYouGaveYourself":null,"finalNote":null,"signatureLine":null,"today":null,"build":null,"move":null,"release":null,"reset":null}$movejson$::jsonb WHERE