UPDATE care_chart_week_content SET move = $movejson${"format":"sections","reset":"A few relaxed breaths before you begin — always, every tier, from here on","move":"Warm-up walk, folded into Rebuild/Thrive below","recoveryRoute":null,"build":["Mini Squats 6, Wall Angels 6, Supported calf raises 8 (Restore)","Two rounds: Mini Squats 8, Supported Lateral Step 8 per side, Wall Angels 8, Standing Hip Abduction 8 per side (Rebuild)","10 minute warm-up walk, then two rounds: Mini Squats 10, Supported Lateral Step 10 per side, Wall Angels 10, Standing Hip Abduction 8 per side (Thrive)"],"release":"Cool down gently, whatever that looks like today","door":null,"exercise":{"name":"Mini Squats","focus":"functional leg strength","benefit":"Mirrors the sit-to-stand motion you'll do constantly once the baby arrives.","mistake":"Letting your knees cave inward.","tip":"Press through your whole foot, knees tracking over your toes."},"inRealLife":null,"why":"The plan adapts now because energy commonly starts returning around this point — but adapting again if it doesn't is just as correct a response.","quote":null,"note":null,"safety":"Use stable support, breathe continuously, and keep effort conversational throughout. Stop for pain, bleeding, dizziness, chest pain, breathlessness before exertion, fluid leakage, calf pain or swelling, or anything that feels wrong.","recovery":null,"reflectionPrompt":null,"closingLabel":"If today doesn't happen","closingText":"Your routine is allowed to disappear for a day too, and reappear whenever it's ready.","lookingAhead":"Many women begin to notice a little more energy over the next few weeks. If that's you, we'll gradually build with you. If not, we'll keep meeting you where you are.","progressionNote":null,"clinicalFlag":null,"theme":"Adapt, do not force","mantra":"Your routine is allowed to change before your bump does.","milestone":null,"breathLegacy":null,"philosophy":null,"childLearned":null,"whatYouGaveYourself":null,"finalNote":null,"sig