UPDATE care_chart_week_content SET move = $movejson${"format":"sections","reset":"A few relaxed breaths before you begin","move":"10 minute walk (Rebuild) / 20 minutes conversational aerobic activity (Thrive)","recoveryRoute":null,"build":["5 minutes: Seated Band Row, Standing Hip Abduction, calf stretching (Rebuild)","One easy round: Heel-to-toe balance near support, Seated Band Row, Standing Hip Abduction — 8 each (Thrive)"],"release":"Calf stretch and a few slow breaths to finish","door":null,"exercise":{"name":"Seated Band Row","focus":"upper-back strength","benefit":"Builds the pulling strength that supports your posture as your chest changes.","mistake":"Shrugging your shoulders up to your ears.","tip":"Squeeze your shoulder blades together, not up."},"inRealLife":null,"why":"Movement can calm appointment nerves because physical movement helps regulate your nervous system in a way that just thinking calmly often can't.","quote":null,"note":null,"safety":"Use stable support, breathe continuously, and keep effort conversational throughout. Stop for pain, bleeding, dizziness, chest pain, breathlessness before exertion, fluid leakage, calf pain or swelling, or anything that feels wrong.","recovery":null,"reflectionPrompt":null,"closingLabel":"If today doesn't happen","closingText":"Ready for today's session doesn't mean perfectly available for it, either — that's fine.","lookingAhead":"Next week brings a little more strength work as your body keeps adjusting — still nothing that asks for perfect calm first.","progressionNote":null,"clinicalFlag":null,"theme":"Questions belong in the room","mantra":"Prepared does not mean perfectly calm.","milestone":null,"breathLegacy":null,"philosophy":null,"childLearned":null,"whatYouGaveYourself":null,"finalNote":null,"signatureLine":null,"tiers":null,"today":null}$movejson$::jsonb WHERE week_number = 11;
