UPDATE care_chart_week_content SET move = $movejson${"format":"sections","reset":"5 minute warm-up (Thrive) or a few relaxed breaths (Restore/Rebuild)","move":"7 minute walk (Rebuild) / 15 minutes walking, swimming, or cycling (Thrive)","recoveryRoute":null,"build":["Choose your two favourite movements from this trimester — 5 minutes total (Restore)","One round: Mini Squats 10, Clamshells (skip if any pelvic-girdle discomfort) 10 per side, Wall Angels 10 (Rebuild)","One to two easy strength rounds, mixing in whichever exercises from this trimester felt best (Thrive)"],"release":"5 minute cool-down","door":null,"exercise":{"name":"Supported Lateral Step","focus":"sideways hip stability","benefit":"Most daily movement trains front-to-back — this fills a real gap most routines miss entirely.","mistake":"Rushing side to side without control.","tip":"Step slowly enough that you could stop mid-step at any point."},"inRealLife":null,"why":"This trimester ends without a dramatic finish because there's no test to pass at week 13 — just a body that's been quietly adapting the whole time.","quote":null,"note":"This week is a real handoff into Second trimester — notice which of this trimester's movements you'd want to keep. From here, expect the exercise list to widen further as your body's needs shift.","safety":"Use stable support, breathe continuously, and keep effort conversational throughout. Stop for pain, bleeding, dizziness, chest pain, breathlessness before exertion, fluid leakage, calf pain or swelling, or anything that feels wrong.","recovery":null,"reflectionPrompt":null,"closingLabel":"If today doesn't happen","closingText":"However this week actually went, look how much you've already carried to get here.","lookingAhead":"Second trimester often brings real relief for many mothers — more energy, less nausea — and the exercise list will widen to match. If it doesn't happen for you right away, we'll adjust there too, the same way we have all along.","progressionNote":null,"clinicalFlag":null,"theme":"First-trimester graduation","mantra":"Look how much you have already carried.","milestone":null,"breathLegacy":null,"philosophy":null,"childLearned":null,"whatYouGaveYourself":null,"finalNote":null,"signatureLine":null,"tiers":null,"today":null}$movejson$::jsonb WHERE week_number = 13;
