UPDATE care_chart_week_content SET move = $movejson${"format":"sections","reset":"Breathe into your belly, hand resting on it, five breaths","move":"10 minute walk (Rebuild) / 20 minutes conversational aerobic activity (Thrive)","recoveryRoute":null,"build":["Mini Squats 8, Wall Angels 8 (Restore)","Two rounds: Mini Squats 10, Standing Row (light band) 10, Wall Angels 10 (Rebuild)","Two to three rounds: Mini Squats 12, Standing Row 12, Side-Lying Hip Abduction 12 per side, Glute Bridge 12 (Thrive)"],"release":"Shoulder rolls and a few slow breaths","door":null,"exercise":{"name":"Standing Row","focus":"upper-back strength and posture","benefit":"Continues supporting the posture shifts already underway, and sets you up for the heavier front-carrying load coming later in pregnancy and after birth.","mistake":"Using momentum or swinging instead of a controlled pull.","tip":"Squeeze your shoulder blades together and pause briefly at the end of each pull."},"inRealLife":"This strength becomes surprisingly useful once you're feeding, carrying, and soothing a newborn.","why":"Not everyone feels movement by 16 weeks, and that's completely normal too — first pregnancies especially can take a few more weeks.","quote":null,"note":"If you're not feeling movement yet, that's expected at this stage — most mothers do by around weeks 20-22.","safety":"Same core guidance as week 14 — stable support, continuous breathing, avoid extended flat-on-back positions. Stop for pain, bleeding, dizziness, chest pain, breathlessness, fluid leakage, calf pain/swelling, or regular tightening that doesn't ease with rest.","recovery":null,"reflectionPrompt":null,"closingLabel":"Notice this","closingText":"whether or not you've felt movement yet, your body is already doing the quiet work of building fingers, eyelashes, and a heartbeat you may have already heard.","lookingAhead":"Your centre of gravity is beginning a genuine shift over the next few weeks — small posture and balance changes are a normal part of that.","progressionNote":null,"clinicalFlag":null,"theme":"Feeling flutters","mantra":"However it arrives, it's yours to notice.","milestone":null,"breathLegacy":null,"philosophy":null,"childLearned":null,"whatYouGaveYourself":null,"finalNote":null,"signatureLine":null,"tiers":null,"today":null}$movejson$::jsonb WHERE week_number = 16;
UPDATE care_chart_week_content SET move = $movejson${"format":"sections","reset":"Sit or stand tall, three slow breaths","move":"10 minute walk (Rebuild) / 20 minutes conversational aerobic activity (Thrive)","recoveryRoute":null,"build":["Wall Angels 8, Wall Pelvic Tilts 8 (Restore)","Two rounds: Thoracic Rotations (seated) 8 per side, Mini Squats 10, Wall Angels 10 (Rebuild)","Two to three rounds: Thoracic Rotations 10 per side, Mini Squats 12, Standing Row 12, Glute Bridge 12 (Thrive)"],"release":"Seated side stretch, both sides","door":null,"exercise":{"name":"Thoracic Rotations (seated)","focus":"upper-back mobility as your ribcage expands","benefit":"Counters the compressed, hunched feeling that can build as your uterus rises.","mistake":"Rotating from your lower back or hips instead of your ribcage.","tip":"Sit tall, cross your hands at your chest, and rotate slowly from your ribs."},"inRealLife":"The same mobility that eases this stiffness now helps you turn comfortably to reach for your baby from a car seat or crib later.","why":"Postural changes are mechanical, not a sign you're doing something wrong — your body is genuinely rearranging around a new centre of gravity.","quote":null,"note":null,"safety":"Same core guidance as week 14 — stable support, continuous breathing, avoid extended flat-on-back positions. Stop for pain, bleeding, dizziness, chest pain, breathlessness, fluid leakage, calf pain/swelling, or regular tightening that doesn't ease with rest.","recovery":null,"reflectionPrompt":null,"closingLabel":"If today doesn't happen","closingText":"sitting tall for even a moment today still counts, even without a full session.","lookingAhead":"The anatomy scan often happens around this point over the next few weeks — many mothers feel a mix of excitement and nerves heading into it, and that's completely normal.","progressionNote":null,"clinicalFlag":null,"theme":"Posture under new pressure","mantra":"A changing shape deserves changing support, not criticism.","milestone":null,"breathLegacy":null,"philosophy":null,"childLearned":null,"whatYouGaveYourself":null,"finalNote":null,"signatureLine":null,"tiers":null,"today":null}$movejson$::jsonb WHERE week_number = 17;
UPDATE care_chart_week_content SET move = $movejson${"format":"sections","reset":"A slow breath in, longer breath out, five times","move":"10 minute walk (Rebuild) / 20 minutes conversational aerobic activity (Thrive)","recoveryRoute":null,"build":["Bird Dog 6 per side, Wall Angels 8 (Restore)","Two rounds: Bird Dog 8 per side, Mini Squats 10, Standing Row 10 (Rebuild)","Two to three rounds: Bird Dog 10 per side, Mini Squats 12, Standing Row 12, Glute Bridge 12 (Thrive)"],"release":"A few slow breaths, wherever you are","door":null,"exercise":{"name":"Bird Dog","focus":"core and balance coordination","benefit":"A steady, familiar movement that can help settle scan-day nerves through your body, not just your thoughts.","mistake":"Letting your lower back arch as you extend.","tip":"Keep your back flat, like a tabletop, the whole time."},"inRealLife":"The steady coordination this builds is the same kind you'll use balancing a baby on one arm while doing something else with the other.","why":"Movement can genuinely help settle appointment anxiety — it gives your nervous system somewhere to put the energy instead of just sitting with it.","quote":null,"note":null,"safety":"Same core guidance as week 14 — stable support, continuous breathing, avoid extended flat-on-back positions. Stop for pain, bleeding, dizziness, chest pain, breathlessness, fluid leakage, calf pain/swelling, or regular tightening that doesn't ease with rest.","recovery":null,"reflectionPrompt":null,"closingLabel":"If today doesn't happen","closingText":"whatever today held instead of movement, it still counted as caring for yourself through a big week.","lookingAhead":"Round ligament twinges — quick, sharp pulls along your lower belly or hip when you move suddenly — are common over the next few weeks as everything stretches. We'll adjust the plan to work around them.","progressionNote":null,"clinicalFlag":null,"theme":"The anatomy scan","mantra":"You don't need to already be calm to walk in the door.",