UPDATE care_chart_week_content SET move = $movejson${"format":"sections","reset":"Three slow, unhurried breaths before you move","move":"10 minute walk, slow and steady (Rebuild) / 20 minutes conversational aerobic activity (Thrive)","recoveryRoute":null,"build":["Wall Pelvic Tilts 8, Side-Lying Clamshell 8 per side (Restore)","Two rounds: Standing Wood Chop (light) 8 per side, Mini Squats 10, Wall Angels 10 (Rebuild)","Two to three rounds: Standing Wood Chop 10 per side, Mini Squats 12, Standing Row 12, Glute Bridge 12 (Thrive)"],"release":"Gentle hip-opener stretch, both sides","door":null,"exercise":{"name":"Standing Wood Chop (light)","focus":"controlled rotational core strength","benefit":"Trains your core to control rotation safely, which can actually ease the sharp pulls that come from sudden, untrained twisting.","mistake":"Twisting fast or jerkily instead of slow and controlled.","tip":"Move slowly enough that you could stop at any point in the rotation."},"inRealLife":"Controlled rotation like this mirrors the twisting reach you'll do constantly — picking a toy up off the floor while holding your baby.","why":"Round ligament pain happens because the ligaments supporting your growing uterus are stretching quickly — it's uncomfortable, not dangerous, and slow, controlled movement usually helps more than stillness.","quote":null,"note":"If sudden sharp pulls bother you today, move more slowly and avoid quick direction changes — this discomfort is common and isn't a sign to stop moving altogether.","safety":"Same core guidance as week 14 — stable support, continuous breathing, avoid extended flat-on-back positions. Stop for pain, bleeding, dizziness, chest pain, breathlessness, fluid leakage, calf pain/swelling, or regular tightening that doesn't ease with rest.","recovery":null,"reflectionPrompt":null,"closingLabel":"If today doesn't happen","closingText":"slowing down today because of a twinge is exactly the right response, not a setback.","lookingAhead":"Week 20 is often thought of as the halfway point of pregnancy — a good moment to notice how far you've already come.","progressionNote":null,"clinicalFlag":"This is a controlled standing rotation movement during pregnancy — worth having an OB/GYN and a women's health physiotherapist scrutinise specifically before this is locked. If they'd prefer a pure anti-rotation alternative instead (e.g. a light Pallof Press), that's the decision point to make it here.","theme":"Round ligament pain","mantra":"A stretch is not the same as a warning sign.","milestone":null,"breathLegacy":null,"philosophy":null,"childLearned":null,"whatYouGaveYourself":null,"finalNote":null,"signatureLine":null,"tiers":null,"today":null}$movejson$::jsonb WHERE week_number = 19;
UPDATE care_chart_week_content SET move = $movejson${"format":"sections","reset":"Three slow breaths, hand resting on your belly","move":"10 minute walk (Rebuild) / 20 minutes conversational aerobic activity (Thrive)","recoveryRoute":null,"build":["Mini Squats 8, Wall Angels 8 (Restore)","Two rounds: Glute Bridge (propped up on a cushion, not flat) 10, Mini Squats 10, Standing Row 10 (Rebuild)","Two to three rounds: Glute Bridge (propped) 12, Mini Squats 12, Standing Wood Chop 10 per side, Side-Lying Hip Abduction 12 per side (Thrive)"],"release":"A few slow breaths, sitting or side-lying","door":null,"exercise":{"name":"Glute Bridge (propped)","focus":"glute activation and pelvic support","benefit":"Keeps building the strength that supports your posture as your bump grows, now done propped up rather than flat.","mistake":"Lying fully flat on your back for the whole set.","tip":"Prop your upper body on a cushion, or hold the bridge briefly rather than for long stretches."},"inRealLife":"This is the same strength that will make picking your baby up off the floor, again and again, feel less taxing on your back.","why":"Reaching the halfway point is worth pausing on, even briefly — not for what's ahead, but for everything your body has already carried you through.","quote":null,"note":"From this week, if any position asks you to lie flat on your back, prop your upper body up on a cushion or wall instead, or swap to the side-lying version — this keeps blood flow comfortable for longer holds.","safety":"Use stable support, breathe continuously, and keep effort conversational throughout. From around week 20, avoid lying flat on your back for more than a minute or two — side-lying or propped-up versions work just as well. Stop for pain, bleeding, dizziness, chest pain, breathlessness before exertion, fluid leakage, calf pain or swelling, regular tightening that doesn't ease with rest, or anything that feels wrong.","recovery":null,"reflectionPrompt":"What's one thing you're proud of your body for this trimester?","closingLabel":"Notice this","closingText":"take a moment today to notice something your body can do now that it couldn't a few months ago.","lookingAhead":"Over the next few weeks, expect a bit more focus on balance and endurance as your bump continues to grow and shift your centre of gravity further.","progressionNote":null,"clinicalFlag":null,"theme":"Halfway there","mantra":"Halfway is not just a math fact — it's a milestone worth noticing.","milestone":null,"breathLegacy":null,"philosophy":null,"childLearned":null,"whatYouGaveYourself":null,"finalNote":null,"signatureLine":null,"tiers":null,"today":null}$movejson$::jsonb WHERE week_number = 20;
