UPDATE care_chart_week_content SET move = $movejson${"format":"sections","reset":"360° Breathing, five rounds, hand resting on the side of your ribs","move":"10 minute walk (Rebuild) / 15-20 minutes conversational activity (Thrive)","recoveryRoute":null,"build":["Wall Pelvic Tilts 8, Side-Lying Hip Abduction 8 per side (Restore)","Two rounds: Mini Squats 10, Standing Row 10, Cat-Cow 8 (Rebuild)","Two rounds: Mini Squats 12, Standing Row 12, Seated Pelvic Tilts (on a ball or sturdy chair) 10, Glute Bridge (propped) 12 (Thrive)"],"release":"Seated Butterfly Stretch, 1 minute","door":null,"exercise":{"name":"Seated Pelvic Tilts (on a ball or chair)","focus":"pelvis and lower-back mobility","benefit":"Gently mobilises the same area that will do real work during labour and delivery.","mistake":"Forcing a big range instead of a small, controlled rock.","tip":"Let your breath lead the movement, not the other way around."},"inRealLife":"This same gentle rocking motion is often instinctively what mothers do to soothe a crying baby — you're already practising it.","why":"Getting to know your baby's usual movement pattern over these next few weeks matters more than counting a specific number — follow whatever guidance your own care team gives you for what to watch for.","quote":null,"note":"If movement ever feels notably different or reduced from your baby's usual pattern, contact your care provider rather than waiting to see.","safety":"Same core guidance as week 27 — stable support, continuous breathing, avoid extended flat-on-back positions. Stop for pain, bleeding, dizziness, breathlessness, fluid leakage, leg swelling/calf pain, or regular tightening that doesn't ease with rest.","recovery":null,"reflectionPrompt":null,"closingLabel":"A gentle fact","closingText":"every baby has their own pattern — the goal is knowing yours, not matching anyone else's.","lookingAhead":"Your lower back may start carrying more noticeably over the next few weeks as your bump's weight shifts further forward.","progressionNote":null,"clinicalFlag":null,"theme":"Counting kicks, gently","mantra":"Getting to know your baby's patterns is not a test to pass.","milestone":null,"breathLegacy":null,"philosophy":null,"childLearned":null,"whatYouGaveYourself":null,"finalNote":null,"signatureLine":null,"tiers":null,"today":null}$movejson$::jsonb WHERE week_number = 28;
UPDATE care_chart_week_content SET move = $movejson${"format":"sections","reset":"360° Breathing, five rounds","move":"10 minute walk (Rebuild) / 15-20 minutes conversational activity (Thrive)","recoveryRoute":null,"build":["Cat-Cow 8, Wall Angels 8 (Restore)","Two rounds: Standing Supported Forward Lean (hands on a wall or counter, hips back) 30 sec hold, Mini Squats 10, Standing Row 10 (Rebuild)","Two rounds: Standing Supported Forward Lean 45 sec, Mini Squats 12, Standing Row 12, Side-Lying Hip Abduction 12 per side (Thrive)"],"release":"Standing Supported Forward Lean, one more slow hold","door":null,"exercise":{"name":"Standing Supported Forward Lean","focus":"relieving lower-back load through a hip hinge","benefit":"Takes weight off your lower spine by shifting it through your hips and arms instead.","mistake":"Rounding your back instead of hinging from the hips.","tip":"Keep your spine long, hips reaching back, like a shallow bow."},"inRealLife":"This exact position is one many mothers find themselves drawn to during labour — leaning forward onto a partner, a wall, or a bed is instinctive relief, and you're practising it now.","why":"Backaches increase now because your growing bump is shifting your whole spine's alignment — this isn't a sign of weakness, it's simple mechanics.","quote":null,"note":null,"safety":"Same core guidance as week 27 — stable support, continuous breathing, avoid extended flat-on-back positions. Stop for pain, bleeding, dizziness, breathlessness, fluid leakage, leg swelling/calf pain, or regular tightening that doesn't ease with rest.","recovery":null,"reflectionPrompt":null,"closingLabel":"If today doesn't happen","closingText":"resting your back today is still caring for it, even without a formal session.","lookingAhead":"Braxton Hicks — practice tightenings — often become more noticeable over the next few weeks. We'll talk about how to tell them apart from the real thing.","progressionNote":null,"clinicalFlag":null,"theme":"Backaches and shifting weight","mantra":"Your back is doing real structural work right now.","milestone":null,"breathLegacy":null,"philosophy":null,"childLearned":null,"whatYouGaveYourself":null,"finalNote":null,"signatureLine":null,"tiers":null,"today":null}$movejson$::jsonb WHERE week_number = 29;
UPDATE care_chart_week_content SET move = $movejson${"format":"sections","reset":"360° Breathing, five rounds — notice how your ribs move as you breathe through any tightening you feel","move":"8-10 minute walk (Rebuild) / 15 minutes conversational activity (Thrive)","recoveryRoute":null,"build":["Wall Pelvic Tilts 8, Ankle Circles 8 per side (Restore)","Two rounds: Cat-Cow 8, Mini Squats 8, Standing Row 8 (Rebuild)","Two rounds: Cat-Cow 10, Mini Squats 10, Standing Supported Forward Lean 30 sec, Side-Lying Hip Abduction 10 per side (Thrive)"],"release":"360° Breathing, a few slow rounds","door":null,"exercise":{"name":"Cat-Cow (birth-prep framing)","focus":"moving through tightening rather than freezing","benefit":"Moving through a Braxton Hicks tightening, rather than staying rigid, often makes it pass more comfortably.","mistake":"Holding your breath through the tightening.","tip":"Keep breathing slowly through it — keep the movement going if it's comfortable to."},"inRealLife":"Learning to move through discomfort instead of freezing is a skill you'll use again in early labour.","why":"Braxton Hicks are irregular, don't intensify, and usually ease with rest or a position change — the guidance for anything different (regular, rhythmic tightening, or tightening before 37 weeks that doesn't ease with rest) is to contact your care provider rather than wait it out.","quote":null,"note":"If breathlessness ever comes on suddenly, feels severe, happens at rest, or comes with chest pain, fainting, a racing heart, or one-sided leg swelling, treat it as urgent and seek care right away.","safety":"Use stable support, breathe continuously, and keep effort conversational throughout. Continue avoiding extended flat-on-back positions — side-lying or propped-up versions work just as well. Stop for pain, bleeding, dizziness, chest pain, breathlessness at rest or with fainting/palpitations, fluid leakage, one-sided leg swelling or calf pain, or any regular, rhythmic tightening that doesn't ease with rest — especially before 37 weeks.","recovery":null,"reflectionPrompt":null,"closingLabel":"Notice this","closingText":"however Braxton Hicks show up for you this week, your body is simply rehearsing something it already knows how to do.","lookingAhead":"Over the next couple of weeks, some mild swelling in your feet and ankles is common — movement actually helps here, more than rest alone.","progressionNote":null,"clinicalFlag":null,"theme":"Braxton Hicks, real vs. practice","mantra":"Your body is rehearsing, not performing yet.","milestone":null,"breathLegacy":null,"philosophy":null,"childLearned":null,"whatYouGaveYourself":null,"finalNote":null,"signatureLine":null,"tiers":null,"today":null}$movejson$::jsonb WHERE week_number = 30;
UPDATE care_chart_week_content SET move = $movejson${"format":"sections","reset":"360° Breathing, five rounds, focusing the breath sideways into your ribs rather than down into your belly","move":"8-10 minute walk (Rebuild) / 15 minutes conversational activity (Thrive)","recoveryRoute":null,"build":["Wall Angels 8, Ankle Circles 8 per side (Restore)","Two rounds: Mini Squats 8, Standing Row 8, Seated Pelvic Tilts 8 (Rebuild)","Two rounds: Mini Squats 10, Standing Row 10, Cat-Cow 8, Side-Lying Hip Abduction 10 per side (Thrive)"],"release":"360° Breathing, slow and unhurried","door":null,"exercise":{"name":"360° Breathing (featured)","focus":"breathing capacity as your lungs have less room","benefit":"Since your diaphragm has less room to drop, breathing wide into your ribs — not just down — gets more air in with less effort.","mistake":"Trying to take one huge breath instead of several steady ones.","tip":"Think \"wide,\" not \"deep.\""},"inRealLife":"This same wide breathing is exactly what labour breathing techniques are built on — you've already been practising it since week one.","why":"Your uterus is now pressing up against your diaphragm, genuinely reducing how much room your lungs have — shortness of breath at this stage is a mechanical fact, not deconditioning.","quote":null,"note":null,"safety":"Same core guidance as week 27 — stable support, continuous breathing, avoid extended flat-on-back positions. Stop for pain, bleeding, dizziness, breathlessness, fluid leakage, leg swelling/calf pain, or regular tightening that doesn't ease with rest.","recovery":null,"reflectionPrompt":null,"closingLabel":"A gentle fact","closingText":"breathlessness climbing stairs right now says nothing about your fitness — it's simply less room to breathe.","lookingAhead":"Mild swelling in your feet and ankles is common over the next few weeks — we'll lean more on circulation-friendly movement to help.","progressionNote":null,"clinicalFlag":null,"theme":"Full lungs, shorter breaths","mantra":"Feeling breathless is mechanical, not a sign you're unfit.","milestone":null,"breathLegacy":null,"philosophy":null,"childLearned":null,"whatYouGaveYourself":null,"finalNote":null,"signatureLine":null,"tiers":null,"today":null}$movejson$::jsonb WHERE week_number = 31;
UPDATE care_chart_week_content SET move = $movejson${"format":"sections","reset":"360° Breathing, five rounds","move":"8-10 minute walk, ideally with feet elevated afterward (Rebuild) / 15 minutes conversational activity (Thrive)","recoveryRoute":null,"build":["Ankle Circles 10 per side, Ankle Pumps 15 (Restore)","Two rounds: Standing Calf Raises 10, Mini Squats 8, Standing Row 8 (Rebuild)","Two rounds: Standing Calf Raises 12, Mini Squats 10, Cat-Cow 8, Side-Lying Hip Abduction 10 per side (Thrive)"],"release":"Feet elevated, ankle circles, a few slow breaths","door":null,"exercise":{"name":"Ankle Pumps and Circles","focus":"circulation in your lower legs","benefit":"Your calf muscles act like a pump for blood flow back up from your feet — genuinely useful against swelling, not just symbolic.","mistake":"Skipping this because it feels too small to matter.","tip":"Little and often beats one long session — do a set whenever you think of it."},"inRealLife":"This is the exact same movement from week one of this whole journey — sometimes the smallest tools stay the most useful the whole way through.","why":"Swelling increases now partly because your growing uterus puts more pressure on the veins returning blood from your legs — movement, not stillness, is usually the better response.","quote":null,"note":"Sudden, one-sided leg swelling with pain or redness is different from ordinary pregnancy swelling and needs prompt medical attention.","safety":"Same core guidance as week 27 — stable support, continuous breathing, avoid extended flat-on-back positions. Stop for pain, bleeding, dizziness, breathlessness, fluid leakage, leg swelling/calf pain, or regular tightening that doesn't ease with rest.","recovery":null,"reflectionPrompt":null,"closingLabel":"If today doesn't happen","closingText":"putting your feet up today is a completely valid form of caring for your circulation too.","lookingAhead":"Pelvic pressure — a heavier, lower feeling — often becomes more noticeable over the next few weeks as your baby continues growing.","progressionNote":null,"clinicalFlag":null,"theme":"Swelling and circulation","mantra":"Movement is often more helpful here than rest.","milestone":null,"breathLegacy":null,"philosophy":null,"childLearned":null,"whatYouGaveYourself":null,"finalNote":null,"signatureLine":null,"tiers":null,"today":null}$movejson$::jsonb WHERE week_number = 32;
UPDATE care_chart_week_content SET move = $movejson${"format":"sections","reset":"360° Breathing, five rounds, exhaling with a soft, relaxed release through your pelvic floor rather than a squeeze","move":"8-10 minute walk (Rebuild) / 15 minutes conversational activity (Thrive)","recoveryRoute":null,"build":["Wall Pelvic Tilts 8, Seated Butterfly Stretch 1 min (Restore)","Two rounds: Cat-Cow 8, Seated Pelvic Tilts 8, Standing Row 8 (Rebuild)","Two rounds: Cat-Cow 10, Seated Pelvic Tilts 10, Standing Calf Raises 10, Side-Lying Hip Abduction 10 per side (Thrive)"],"release":"Seated Butterfly Stretch, 1-2 minutes","door":null,"exercise":{"name":"Seated Butterfly Stretch","focus":"hip and inner-thigh opening","benefit":"Gently opens the same area that will need to move well during labour and delivery.","mistake":"Pressing your knees down forcefully.","tip":"Let gravity do the work — no need to push."},"inRealLife":"This same open, seated position is one many mothers find genuinely comfortable in the final weeks, and again postpartum while feeding.","why":"That heavier, lower feeling is your baby settling further down and forward — a completely normal part of the body preparing for birth, not a sign of a problem on its own.","quote":null,"note":null,"safety":"Same core guidance as week 27 — stable support, continuous breathing, avoid extended flat-on-back positions. Stop for pain, bleeding, dizziness, breathlessness, fluid leakage, leg swelling/calf pain, or regular tightening that doesn't ease with rest.","recovery":null,"reflectionPrompt":null,"closingLabel":"Notice this","closingText":"your body is now doing preparation work for birth that has nothing to do with how many sessions you complete this week.","lookingAhead":"The next few weeks often bring more conversation with your care team about your pelvic floor and preparing for labour and delivery.","progressionNote":null,"clinicalFlag":null,"theme":"Pelvic pressure increases","mantra":"Heaviness is not the same as something being wrong.","milestone":null,"breathLegacy":null,"philosophy":null,"childLearned":null,"whatYouGaveYourself":null,"finalNote":null,"signatureLine":null,"tiers":null,"today":null}$movejson$::jsonb WHERE week_number = 33;
UPDATE care_chart_week_content SET move = $movejson${"format":"sections","reset":"360° Breathing, five rounds — this week, pair the exhale with consciously softening and releasing your pelvic floor, rather than squeezing it","move":"8-10 minute walk (Rebuild) / 15 minutes conversational activity (Thrive)","recoveryRoute":null,"build":["Wall Pelvic Tilts 8, Seated Butterfly Stretch 1 min (Restore)","Two rounds: Supported Deep Squat Hold (holding a stable support) 15 sec x2, Cat-Cow 8, Standing Row 8 (Rebuild)","Two rounds: Supported Deep Squat Hold 20 sec, Cat-Cow 10, Seated Pelvic Tilts 10, Side-Lying Hip Abduction 10 per side (Thrive)"],"release":"360° Breathing with a relaxed pelvic-floor exhale, a few slow rounds","door":null,"exercise":{"name":"Supported Deep Squat Hold","focus":"pelvic opening and hip mobility for birth","benefit":"Gently opens your pelvis in a position similar to some labour and birthing positions.","mistake":"Letting your heels lift off the ground.","tip":"Hold onto something stable, only go as deep as feels comfortable, keep your heels down."},"inRealLife":"This same squat position is one many care providers actively encourage during labour itself — you're practising a position you may genuinely use.","why":"Learning to relax your pelvic floor on purpose is just as important for birth as strengthening it — this week's breathing starts training that release deliberately, not just the squeeze.","quote":null,"note":null,"safety":"Use stable support, breathe continuously, and keep effort conversational throughout. Continue avoiding extended flat-on-back positions — side-lying or propped-up versions work just as well. Stop for pain, bleeding, dizziness, chest pain, breathlessness at rest or with fainting/palpitations, fluid leakage, one-sided leg swelling or calf pain, or any regular, rhythmic tightening that doesn't ease with rest — especially before 37 weeks.","recovery":null,"reflectionPrompt":null,"closingLabel":"A gentle fact","closingText":"relaxing on purpose is a real, practisable skill for birth, not just a nice idea.","lookingAhead":"Your Group B Strep (GBS) screening usually happens in the next couple of weeks — a routine swab test, not a sign of concern.","progressionNote":null,"clinicalFlag":null,"theme":"Preparing your pelvic floor","mantra":"The same breath that calmed you in week one is now preparing you to give birth.","milestone":null,"breathLegacy":null,"philosophy":null,"childLearned":null,"whatYouGaveYourself":null,"finalNote":null,"signatureLine":null,"tiers":null,"today":null}$movejson$::jsonb WHERE week_number = 34;
UPDATE care_chart_week_content SET move = $movejson${"format":"sections","reset":"360° Breathing, five rounds","move":"8-10 minute walk (Rebuild) / 15 minutes conversational activity (Thrive)","recoveryRoute":null,"build":["Ankle Circles 8 per side, Wall Pelvic Tilts 8 (Restore)","Two rounds: Cat-Cow 8, Seated Pelvic Tilts 8, Standing Calf Raises 8 (Rebuild)","Two rounds: Cat-Cow 10, Supported Deep Squat Hold 15 sec, Seated Butterfly Stretch 1 min, Side-Lying Hip Abduction 10 per side (Thrive)"],"release":"Seated Butterfly Stretch or Cat-Cow, whichever feels better today","door":null,"exercise":{"name":"Cat-Cow (comfort-first framing)","focus":"comfort-first spinal movement","benefit":"At this stage, comfort is doing just as much work as strength.","mistake":"Pushing for a bigger range than feels good.","tip":"The smallest, slowest version still counts fully."},"inRealLife":"This is exactly the kind of small relief movement you'll reach for constantly once you're recovering and holding a newborn.","why":"Slowing down now isn't a lesser version of this programme — it's the correct response to a body doing its heaviest carrying of the entire pregnancy.","quote":null,"note":"Ask your care provider about perineal massage in these final weeks if you're curious — it's a common, optional topic worth raising directly with them rather than guessing on your own.","safety":"Same core guidance as week 27 — stable support, continuous breathing, avoid extended flat-on-back positions. Stop for pain, bleeding, dizziness, breathlessness, fluid leakage, leg swelling/calf pain, or regular tightening that doesn't ease with rest.","recovery":null,"reflectionPrompt":null,"closingLabel":"Worth celebrating","closingText":"35 weeks of adapting, again and again, is a real, cumulative achievement — not just today's session.","lookingAhead":"Your GBS screening and the shift into 'early term' both typically happen right around the next couple of weeks.","progressionNote":null,"clinicalFlag":null,"theme":"The final stretch begins","mantra":"Slower is allowed to be the whole pace now.","milestone":null,"breathLegacy":null,"philosophy":null,"childLearned":null,"whatYouGaveYourself":null,"finalNote":null,"signatureLine":null,"tiers":null,"today":null}$movejson$::jsonb WHERE week_number = 35;
