ing and early term","mantra":"Test results are information, not verdicts.","milestone":null,"breathLegacy":null,"philosophy":null,"childLearned":null,"whatYouGaveYourself":null,"finalNote":null,"signatureLine":null,"tiers":null,"today":null}$movejson$::jsonb WHERE week_number = 36;
