 all began.","progressionNote":null,"theme":"Play, remembered","mantra":"This is the first time in a year movement gets to just be fun.","childLearned":null,"whatYouGaveYourself":null,"tiers":null,"signatureLine":null,"today":null,"milestone":null,"finalNote":null,"breathLegacy":null,"philosophy":null,"clinicalFlag":null}$movejson$::jsonb WHERE week_number = 84;
