UPDATE care_chart_week_content SET move = $movejson${"format":"sections","theme":"Community and shared movement","mantra":"Moving alongside other mothers can be its own kind of strength.","reset":"360° Breathing, five rounds","today":"Today, actually invite another mother to join you — a walk, a class, or just company while you both move","build":["Squat, 12 reps","Standing Row, 10 reps","Sit-to-Stand, 12 reps"],"release":"A stretch of your choice","door":null,"exercise":{"name":"Movement shared with someone else","focus":"the specific value of moving alongside other mothers","benefit":"Shared movement can bring accountability, connection, and relief that solo sessions genuinely don't offer.","mistake":"Assuming solo movement is always the more serious or effective option.","tip":"Actually send the message today, rather than just considering it."},"inRealLife":"Watching you maintain real friendships and community, including through shared movement, teaches your child that connection matters too.","why":"Shared movement offers real, specific benefits — accountability, connection, and relief from isolation — that solo training doesn't automatically provide.","quote":null,"note":"Friendships often change genuinely after becoming a mother — some fade, some deepen, and new ones form around this exact stage of life. None of that is a loss to apologise for; it's a normal part of how your circle reshapes itself around who you are now.","safety":"Same core guidance as week 53 — consistency over intensity. Stop for pain, new leaking or heaviness, joint pain that doesn't ease, or anything that feels wrong.","recovery":["A sense of connection through movement, if that's what today involved","Energy adequate for shared or solo activity","Mood generally steady","No pressure to choose one mode permanently over the other"],"reflectionPrompt":null,"closingLabel":"Notice this","closingText":"however today's invitation landed, reaching out at all was worth doing.","lookingAhead":"Over the next couple of weeks, it's worth noticing how your relationship with your own body keeps evolving.","milestone":null,"breathLegacy":null,"philosophy":null,"finalNote":null,"signatureLine":null,"childLearned":null,"whatYouGaveYourself":null,"tiers":null,"recoveryRoute":null,"progressionNote":null,"move":null,"clinicalFlag":null}$movejson$::jsonb WHERE week_number = 111;
