UPDATE care_chart_week_content SET move = $movejson${"format":"sections","theme":"What lasts, without trying","mantra":"Some things you build simply last, without needing to be aimed at anyone.","reset":"360° Breathing, five rounds","today":"20 minutes of your choice","build":["Supported Split Squat, 8 per side","One-Arm Row, 10 per side","Single-Leg Balance with Reach, 8 per side"],"release":"A stretch of your choice","door":null,"exercise":{"name":"Movement done exactly the way that feels most like you","focus":"consistency as its own quiet outcome, not a lesson aimed at anyone","benefit":"Moving today in a way that's simply, honestly yours is enough — it doesn't need to be framed as a lesson for someone else to be worthwhile.","mistake":"Treating every action as needing a purpose beyond itself.","tip":"Move today because it's your practice, full stop — no other reason required."},"inRealLife":"Not everything you do needs to be for them to still matter, to you and to anyone paying attention.","why":"Some of what lasts from these years won't be anything deliberately taught — it'll simply be who you were, consistently, for your own reasons. That's allowed to be enough, with no one needing to learn anything from it.","quote":null,"note":null,"safety":"Same core guidance as always — consistency over intensity. Stop for pain, new leaking or heaviness, joint pain that doesn't ease, or anything that feels wrong.","recovery":["Some peace with things that are simply for you","Mood generally steady","Physical strength continuing to feel solid","Less need to justify actions through their effect on others"],"reflectionPrompt":null,"closingLabel":"Notice this","closingText":"whatever today held, it was allowed to simply be for you.","lookingAhead":"Over the next week, it's worth a real look at the village — the people — who've been part of this with you.","milestone":null,"breathLegacy":null,"philosophy":null,"finalNote":null,"signatureLine":null,"childLearned":null,"whatYouGaveYourself":null,"tiers":null,"recoveryRoute":null,"progressionNote":null,"move":null,"clinicalFlag":null}$movejson$::jsonb WHERE week_number = 153;
