icalFlag":null}$movejson$::jsonb WHERE week_number = 154;
UPDATE care_chart_week_content SET move = $movejson${"format":"sections","theme":"How are you, really","mantra":"This week isn't about exercise. It's about you.","reset":"360° Breathing, five rounds","today":"Whatever feels right today, or nothing at all","build":["360° Breathing, as many rounds as you'd like","A short walk, only if it appeals today"],"release":"Rest, genuinely, if that's what today needs","door":null,"exercise":{"name":"A real pause","focus":"checking in with yourself, nearly three years in","benefit":"A dedicated week to notice how you're doing, emotionally as much as physically, well into Year Three.","mistake":"Assuming check-ins only matter in the earlier years.","tip":"Let this week be about honesty, not output."},"inRealLife":"This kind of honest self-check-in matters for you, regardless of anyone else.","why":"Nearly three years into motherhood is still a genuinely meaningful point to pause and ask how you're actually doing — this doesn't stop mattering just because time has passed.","quote":null,"note":"If sadness, anxiety, or feeling persistently overwhelmed have been present for a while, that deserves real attention from your care provider, however far along you are.","safety":"Consistency over intensity, still. Stop and seek care for pain above 4/10, new leaking or pelvic heaviness with exercise, joint pain that doesn't ease with rest, or anything that feels wrong. Persistent low mood, anxiety, or intrusive thoughts deserve real support at any point.","recovery":["An honest answer to how you're really doing","A sense of who to tell if the answer is \"not great\"","Physical health feeling stable","Some moments of genuine ease, even small ones"],"reflectionPrompt":"How are you, really — not how you're managing, but how you're actually doing?","closingLabel":"A gentle fact","closingText":"asking yourself this honestly, even once, is real and valuable, whatever the answer is.","lookingAhead":"Next week, we gently pick movement back up, at whatever pace feels right after this pause.","milestone":null,"breathLegacy":null,"philosophy":null,"finalNote":null,"signatureLine":null,"childLearned":null,"whatYouGaveYourself":null,"tiers":null,"recoveryRoute":null,"progressionNote":null,"move":null,"clinicalFlag":null}$movejson$::jsonb WHERE week_number = 155;
UPDATE care_chart_week_content SET move = $movejson${"format":"sections","theme":"Your time is a resource too","mantra":"You don't have to spend every free minute productively.","reset":"360° Breathing, five rounds","today":"20 minutes, or spend that time however you actually want to","build":["Bodyweight Squat, 14 reps","Standing Row, 10 reps","Or: nothing at all, spent doing something else entirely"],"release":"A stretch of your choice, or none","door":null,"exercise":{"name":"Twenty minutes, spent however you choose","focus":"time as a real, personal resource, not just a productivity slot","benefit":"This twenty minutes could go to movement, to sitting outside, to reading, or to doing genuinely nothing — all of those are legitimate uses of your own time.","mistake":"Feeling that any time not spent 'improving' something is wasted.","tip":"Notice today that choosing rest or stillness over movement would have been an equally valid choice."},"inRealLife":"Time spent however you want, including on nothing in particular, is a real, quiet form of autonomy.","why":"This practice has never required money — it runs on time. And time itself is a resource you're allowed to spend however you choose, not just on things that look productive. Twenty minutes of movement, twenty minutes of rest, and twenty minutes of doing nothing at all are all legitimate choices.","quote":null,"note":null,"safety":"Same core guidance as always — consistency over intensity. Stop for pain, new leaking or heaviness, joint pain that doesn't ease, or anything that feels wrong.","recovery":["A sense of ownership over how you spend your time","Mood generally steady","Physical strength continuing to feel solid","Comfort with rest being an equally valid choice"],"reflectionPrompt":null,"closingLabel":"A gentle fact","closingText":"however you spent today's twenty minutes, choosing it yourself is what actually matters.","lookingAhead":"Over the next week, rest is worth reframing as part of who you are, not just recovery from what you've done.","milestone":null,"breathLegacy":null,"philosophy":null,"finalNote":null,"signatureLine":null,"childLearned":null,"whatYouGaveYourself":null,"tiers":null,"recoveryRoute":null,"progressionNote":null,"move":null,"clinicalFlag":null}$movejson$::jsonb WHERE week_number = 156;
UPDATE care_chart_week_content SET move = $movejson${"format":"sections","theme":"Rest as identity, not recovery","mantra":"Rest isn't just something you earn. It's something you are allowed to be.","reset":"360° Breathing, five rounds","today":"10-15 minutes, gently","build":["360° Breathing, extra rounds","A short, easy walk"],"release":"Genuine rest, without guilt","door":null,"exercise":{"name":"A deliberately light, unremarkable session","focus":"resting without needing to justify it","benefit":"A light week, taken simply because it appeals, without needing to have 'earned' it through a hard prior week, is real practice of rest as identity.","mistake":"Only allowing rest after visible effort, as though it must be earned.","tip":"Rest today without first finding a reason that justifies it."},"inRealLife":"Rest, chosen simply because you want it, needs no other justification.","why":"Early on, rest was because you were healing. Later, rest was because your body needed recovery. Now, rest can simply be because you want it to be — that shift is real evolution, not indulgence.","quote":null,"note":null,"safety":"Same core guidance as always — consistency over intensity. Stop for pain, new leaking or heaviness, joint pain that doesn't ease, or anything that feels wrong.","recovery":["Comfort resting without guilt","Energy feeling genuinely replenished","Mood generally steady","No need to justify today's rest"],"reflectionPrompt":null,"closingLabel":"If today doesn't happen","closingText":"resting today, without needing to justify it, is exactly the point of this week.","lookingAhead":"Over the next week, it's worth returning to body confidence with fully fresh eyes.","milestone":null,"breathLegacy":null,"philosophy":null,"finalNote":null,"signatureLine":null,"childLearned":null,"whatYouGaveYourself":null,"tiers":null,"recoveryRoute":null,"progressionNote":null,"move":null,"clinicalFlag":null}$movejson$::jsonb WHERE week_number = 157;
