"Next week, it's worth looking at what a more independent child actually gives back to you.","milestone":null,"breathLegacy":null,"philosophy":null,"finalNote":null,"signatureLine":null,"childLearned":null,"whatYouGaveYourself":null,"tiers":null,"recoveryRoute":null,"progressionNote":null,"move":null,"clinicalFlag":null}$movejson$::jsonb WHERE week_number = 158;
