UPDATE care_chart_week_content SET move = $movejson${"format":"sections","theme":"\"I've been there\"","mantra":"You don't have to be an expert to be a comfort to someone.","reset":"360° Breathing, five rounds","today":"20 minutes of your choice","build":["Bodyweight Squat, 14 reps","Standing Row, 10 reps","Sit-to-Stand, 12 reps"],"release":"A stretch of your choice","door":null,"exercise":{"name":"Whichever movement feels familiar and steady today","focus":"showing up steadily, not becoming anyone's instructor","benefit":"You don't need any technical expertise to be a real comfort to a newer mother — steadiness, honesty, and having genuinely been there are enough.","mistake":"Assuming reaching this point means you're now qualified to coach someone else's exercise or recovery.","tip":"If a newer mother reaches out, offer company and honesty, not instructions."},"inRealLife":"You once needed someone to tell you it would be okay. Now you can be that for someone else — as a companion, not a coach.","why":"This isn't about becoming anyone's physiotherapist or exercise coach — that's a different, professional role. What you genuinely have to offer is emotional company: reassurance, perspective, and the simple, honest phrase 'I've been there.' That's real, and it's enough.","quote":null,"note":null,"safety":"Same core guidance as always — consistency over intensity. Stop for pain, new leaking or heaviness, joint pain that doesn't ease, or anything that feels wrong.","recovery":["A real sense of accumulated, shareable experience","Comfort with offering company, not instruction","Mood generally steady","Physical strength continuing to feel solid"],"reflectionPrompt":null,"closingLabel":"Notice this","closingText":"whatever today's session held, the knowledge behind it is real — as company for someone else, not as expertise to teach.","lookingAhead":"Next week is another check-in — the same honest pause as always.","milestone":null,"breathLegacy":null,"philosophy":null,"finalNote":null,"signatureLine":null,"childLearned":null,"whatYouGaveYourself":null,"tiers":null,"recoveryRoute":null,"progressionNote":null,"move":null,"clinicalFlag":null}$movejson$::jsonb WHERE week_number = 164;
